"""Learning Assistant: short technical lessons built from the day's important news and papers.

* Items: the most important news, research, model and tool releases of the last 36 hours, with those that
  mention what the user follows (or match their interests) first.
* Lessons are generated by the configured LLM from the item text only, then grounded like every other AI
  output: sentences carrying numbers, versions or ids the source does not contain are removed.
* Links come only from the curated catalog in app/ai/learning.py (official documentation); the model picks
  topics from that catalog's keys and never writes a URL.
* Everything is stored and served labelled as AI-generated, with the provider and model that wrote it.
"""

from datetime import UTC, date, datetime, timedelta
from typing import Any

from sqlalchemy import delete, select
from sqlalchemy.ext.asyncio import AsyncSession

from app.ai import claims
from app.ai.briefing import local_now
from app.ai.learning import CATALOG, resources_for
from app.ai.pipeline import _article_text, record_usage
from app.ai.prompts import LESSON_VERSION, SYSTEM_LESSON, Lesson, lesson_prompt
from app.ai.providers import AIProviders, ProviderError
from app.ai.scoring import INTEREST_CATEGORIES
from app.core.logging import get_logger
from app.models import AIAnalysis, Article, LearningLesson, User, UserPreference
from app.models.enums import AnalysisKind, ItemType
from app.services.recommendations import mentions

log = get_logger(__name__)

WINDOW = timedelta(hours=36)
LESSON_TYPES = [ItemType.NEWS, ItemType.RESEARCH, ItemType.MODEL_RELEASE, ItemType.TOOL, ItemType.DEVOPS]
LESSONS_PER_DAY = 3
POOL = 40
TOPICS = sorted(CATALOG)


class LessonsDisabledError(Exception):
    """No LLM provider is configured."""


class LessonGenerator:
    def __init__(self, session: AsyncSession, providers: AIProviders, now: datetime | None = None) -> None:
        self.s = session
        self.p = providers
        self.now = now or datetime.now(UTC)

    async def _summary(self, article_id: Any) -> str | None:
        out = await self.s.scalar(
            select(AIAnalysis.output["short_summary"].astext).where(
                AIAnalysis.article_id == article_id,
                AIAnalysis.kind == AnalysisKind.SUMMARY,
                AIAnalysis.valid.is_(True),
            )
        )
        return out or None

    async def pick(
        self, pref: UserPreference | None, n: int = LESSONS_PER_DAY
    ) -> list[tuple[Article, str | None]]:
        """(item, personal reason) for today's lessons: important first, the user's topics before others."""
        rows = (
            (
                await self.s.execute(
                    select(Article)
                    .where(
                        Article.collected_at >= self.now - WINDOW,
                        Article.item_type.in_(LESSON_TYPES),
                        Article.duplicate_of_id.is_(None),
                    )
                    .order_by(Article.importance_score.desc().nulls_last())
                    .limit(POOL)
                )
            )
            .unique()
            .scalars()
            .all()
        )
        followed = [
            *(pref.followed_technologies if pref else []),
            *(pref.followed_providers if pref else []),
        ]
        interests = pref.interests if pref else []
        interest_cats = {c for i in interests for c in INTEREST_CATEGORIES.get(i, set())}

        def personal(a: Article) -> str | None:
            hit = mentions(f"{a.title} {a.description or ''}", followed)
            if hit:
                return f"Because you follow {hit[0]}"
            cats = {c.slug for c in a.categories} & interest_cats
            return "Matches your interests" if cats else None

        ranked = sorted(
            ((a, personal(a)) for a in rows), key=lambda t: (t[1] is None, -(t[0].importance_score or 0))
        )
        return ranked[:n]

    async def generate(self, user: User, lesson_date: date | None = None) -> list[LearningLesson]:
        llm = self.p.llm
        if llm is None:
            raise LessonsDisabledError("AI lessons need an LLM provider (LLM_PROVIDER / LLM_MODEL).")
        pref = await self.s.scalar(select(UserPreference).where(UserPreference.user_id == user.id))
        day = lesson_date or local_now(pref, self.now).date()
        followed = [*(pref.followed_technologies if pref else []), *(pref.followed_providers if pref else [])]
        lessons: list[LearningLesson] = []
        for position, (a, reason) in enumerate(await self.pick(pref)):
            body = _article_text(a)[:6000]
            summary = await self._summary(a.id)
            prompt = lesson_prompt(
                title=a.title,
                source=a.source.name,
                published=a.published_at.isoformat() if a.published_at else None,
                url=a.url,
                body=body,
                summary=summary,
                followed=followed,
                topics=TOPICS,
            )
            try:
                result = await llm.complete_json(SYSTEM_LESSON, prompt, Lesson)
            except ProviderError as exc:
                await record_usage(
                    self.s, "lesson", llm.provider, llm.model, ok=False, error=str(exc), article_id=a.id
                )
                log.warning("lesson_failed", article_id=str(a.id), error=str(exc)[:200])
                continue
            await record_usage(
                self.s,
                "lesson",
                llm.provider,
                llm.model,
                input_tokens=result.usage.input_tokens,
                output_tokens=result.usage.output_tokens,
                cost=result.cost_usd,
                article_id=a.id,
            )
            content = self.ground(a, result.data, "\n".join(filter(None, [a.title, body, summary])), reason)
            if content is None:
                continue
            lessons.append(
                LearningLesson(
                    user_id=user.id,
                    article_id=a.id,
                    lesson_date=day,
                    position=position,
                    content=content,
                    prompt_version=LESSON_VERSION,
                    provider=llm.provider,
                    model=llm.model,
                    created_at=self.now,
                )
            )
        if lessons:  # replace today's set only when the new one is usable
            await self.s.execute(
                delete(LearningLesson).where(
                    LearningLesson.user_id == user.id, LearningLesson.lesson_date == day
                )
            )
            self.s.add_all(lessons)
            await self.s.flush()
        return lessons

    @staticmethod
    def ground(a: Article, data: Lesson, source_text: str, reason: str | None) -> dict[str, Any] | None:
        unsupported: set[str] = set()

        def keep(text: str | None) -> str:
            kept, bad = claims.strip_unsupported(text or "", source_text)
            unsupported.update(bad)
            return kept

        explanation = keep(data.explanation)
        if not explanation:
            return None  # the core of the lesson made claims the source does not support
        points = [p for p in (keep(x) for x in data.key_points) if p]
        topics = [t for t in dict.fromkeys(data.topics) if t in CATALOG]
        categories = [c.slug for c in a.categories if c.slug in CATALOG]
        return {
            "title": keep(data.title) or a.title[:140],
            "explanation": explanation,
            "key_points": points,
            "why_it_matters": keep(data.why_it_matters),
            "try_it": keep(data.try_it) or None,
            "topics": topics,
            # Curated official documentation only: links never come from the model.
            "resources": [r for r in resources_for([*topics, *categories], []) if r["url"]],
            "source": {"article_id": str(a.id), "title": a.title, "url": a.url, "source": a.source.name},
            "personal_reason": reason,
            "unsupported_claims_removed": sorted(unsupported),
            "ai_generated": True,
        }
